	/** Isolates the seven clean runtime labels without the separate raw-entry/null-context failures. */
	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void isolatedNamedRuntimeSelectorsRetainTheirExactBags(boolean nativeEvaluation, @TempDir Path root)
			throws Exception {
		try (Fixture fixture = fixture(root, nativeEvaluation)) {
			List<Executable> checks = new ArrayList<>();
			for (Resource alias : new Resource[] { RDF4J.NIL, SESAME.NIL }) {
				for (Dataset selected : Arrays.asList(null, new SimpleDataset(), selected(true, alias))) {
					MapBindingSet binding = new MapBindingSet();
					binding.addBinding("g", alias);
					BindingSetAssignment values = new BindingSetAssignment();
					values.setBindingNames(Set.of("g"));
					values.setBindingSets(List.of(binding, EmptyBindingSet.getInstance()));
					TupleExpr input = new Join(values, pattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g")));
					Map<Map<String, Value>, Long> expected = new HashMap<>();
					if (selected != null && selected.isExplicitReadDataset()) {
						expected.put(statementRow("urn:population-owner:a", null), 1L);
						expected.put(statementRow(RDF4J.NIL.equals(alias) ? "urn:context-selector:rdf4j-named"
								: "urn:context-selector:sesame-named", alias), 1L);
					} else {
						expected.put(statementRow("urn:population-owner:b", G), 1L);
						expected.put(statementRow("urn:context-selector:rdf4j-named", RDF4J.NIL), 1L);
						expected.put(statementRow("urn:context-selector:sesame-named", SESAME.NIL), 1L);
						expected.put(statementRow("urn:context-selector:blank-named", BLANK), 1L);
						expected.put(statementRow("urn:population-owner:a", alias), 1L);
					}
					assertEquals(expected, publicBag(fixture.oracle, input, selected, EmptyBindingSet.getInstance()),
							"independent complete Memory bag: " + alias + ";" + datasetFields(selected));
					try (Read read = fixture.read(FrontierLeafProbe.EXPLICIT, null, selected)) {
						compare(fixture, read, input, selected, EmptyBindingSet.getInstance(),
								"isolated VALUES/UNDEF NAMED value=" + alias, checks);
					}
				}
			}
			Dataset selected = selected(true, (Resource) null);
			TupleExpr input = pattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"));
			assertEquals(Map.of(statementRow("urn:population-owner:a", null), 1L),
					publicBag(fixture.oracle, input, selected, EmptyBindingSet.getInstance()),
					"an explicitly selected null graph reaches the ordinary NAMED context array");
			try (Read read = fixture.read(FrontierLeafProbe.EXPLICIT, null, selected)) {
				compare(fixture, read, input, selected, EmptyBindingSet.getInstance(), "isolated unbound NAMED null",
						checks);
			}
			assertAll("isolated runtime selector bags, factory native=" + nativeEvaluation, checks);
		}
	}

