	/** Declared scope and graph operand are independent coordinates in programmatically supplied algebra. */
	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void programmaticPathScopeIsIndependentOfContextPresence(boolean nativeEvaluation, @TempDir Path root)
			throws Exception {
		try (Fixture fixture = fixture(root, nativeEvaluation)) {
			List<Executable> checks = new ArrayList<>();
			for (Dataset selected : Arrays.asList(null, selected(false, G), selected(true, G), selected(false))) {
				try (Read read = fixture.read(FrontierLeafProbe.EXPLICIT, null, selected)) {
					for (StatementPattern.Scope scope : StatementPattern.Scope.values()) {
						for (boolean withContext : new boolean[] { false, true }) {
							Var graph = withContext ? Var.of("g", G, false, true) : null;
							ZeroLengthPath zero = new ZeroLengthPath(scope, Var.of("s"), Var.of("o"), graph);
							assertEquals(scope, zero.getScope());
							assertEquals(withContext, zero.getContextVar() != null);
							compare(fixture, read, zero, selected, EmptyBindingSet.getInstance(),
									"declared zero scope=" + scope + ";context=" + withContext, checks);
							for (long minimum : new long[] { 0L, 1L }) {
								Var pathGraph = withContext ? Var.of("g", G, false, true) : null;
								StatementPattern step = new StatementPattern(scope, Var.of("s"), Var.of("p", RDF.TYPE),
										Var.of("o"), pathGraph == null ? null : pathGraph.clone());
								ArbitraryLengthPath path = new ArbitraryLengthPath(scope, Var.of("s"), step, Var.of("o"),
										pathGraph, minimum);
								assertEquals(scope, path.getScope());
								assertEquals(withContext, path.getContextVar() != null);
								compare(fixture, read, path, selected, EmptyBindingSet.getInstance(),
										"declared arbitrary scope=" + scope + ";context=" + withContext + ";min=" + minimum,
										checks);
							}
						}
					}
				}
			}
			assertAll("declared path scopes, factory native=" + nativeEvaluation, checks);
		}
	}

	/** Empty statement selection does not decide zero-length constant identity output. */
	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void emptyGraphSelectionKeepsZeroLengthEndpointSemantics(boolean nativeEvaluation, @TempDir Path root)
			throws Exception {
		try (Fixture fixture = fixture(root, nativeEvaluation)) {
			List<Executable> checks = new ArrayList<>();
			IRI present = VF.createIRI("urn:population-owner:a");
			for (StatementPattern.Scope scope : StatementPattern.Scope.values()) {
				Dataset oppositeOnly = selected(scope == StatementPattern.Scope.DEFAULT_CONTEXTS, G);
				for (Dataset selected : List.of(selected(false), oppositeOnly)) {
					try (Read read = fixture.read(FrontierLeafProbe.EXPLICIT, null, selected)) {
						for (boolean withContext : new boolean[] { false, true }) {
							List<Var[]> endpoints = List.of(
									new Var[] { Var.of("s", present, false, true), Var.of("o", present, false, true) },
									new Var[] { Var.of("s", present, false, true), Var.of("o", G, false, true) },
									new Var[] { Var.of("s", MISSING, false, true), Var.of("o", MISSING, false, true) },
									new Var[] { Var.of("s"), Var.of("o") },
									new Var[] { Var.of("s", MISSING, false, true), Var.of("o") });
							for (int index = 0; index < endpoints.size(); index++) {
								Var[] pair = endpoints.get(index);
								Var graph = withContext ? Var.of("g", G, false, true) : null;
								ZeroLengthPath zero = new ZeroLengthPath(scope, pair[0], pair[1], graph);
								Map<Map<String, Value>, Long> expected = new HashMap<>();
								if (scope == StatementPattern.Scope.DEFAULT_CONTEXTS && (index == 0 || index == 2)) {
									expected.put(Map.of(), 1L);
								} else if (scope == StatementPattern.Scope.DEFAULT_CONTEXTS && index == 4) {
									expected.put(Map.of("o", MISSING), 1L);
								}
								String label = "empty graph zero scope=" + scope + ";context=" + withContext + ";endpoints=" + index;
								if (index != 3 || selected.getDefaultGraphResources().isEmpty()
										&& selected.getNamedGraphResources().isEmpty()) {
									assertEquals(expected, publicBag(fixture.oracle, zero, selected, EmptyBindingSet.getInstance()),
											"independent ordinary zero-length owner: " + label);
								}
								// Both-free enumeration in the ordinary owner has its own context-presence frame.
								// Compare its complete real bag; an empty declared-scope set is not an empty-output oracle.
								compare(fixture, read, zero, selected, EmptyBindingSet.getInstance(), label, checks);
							}
						}
					}
				}
			}
			assertAll("empty-selection zero-length semantics, factory native=" + nativeEvaluation, checks);
		}
	}

